      "logic": "AND",
      "items": [],
      "expression": "WHEN (date_order_violation(project_id,approval_date,first_purchase_date) = TRUE) OR cross_system_consistency(project_id, systems=$compare_systems) = FALSE THEN RISK(\"未立项先实施-跨系统一致性\", level=\"高\", action=\"人工复核/按权限阻断\")",
      "expressionLanguage": "DSL",
