    "code": "SUP-C-PUR-05-02",
    "name": "单一来源依据不足-跨系统一致性",
    "version": "v0.1",
    "type": "字段比对",
    "stage": "事中",
    "level": "高",
    "defaultLevel": "高",
    "enabled": false,
    "status": "草稿",
    "conditions": {
      "id": "group-root",
      "logic": "AND",
      "items": [],
      "expression": "WHEN ((is_null(method) OR method IN [\"缺失\",\"未审批\",\"未通过\",\"\"])) OR cross_system_consistency(request_id, systems=$compare_systems) = FALSE THEN RISK(\"单一来源依据不足-跨系统一致性\", level=\"高\", action=\"人工复核/按权限阻断\")",
      "expressionLanguage": "DSL",
      "detectionText": "将财务、OA、ERP、项目、招采/CRM等系统的同一业务主键进行交叉核验，任一关键字段不一致即升级风险。 监管对象：单一来源依据不足。典型情形：采用单一来源但无不可替代专利、唯一供应商、配套延续等充分证明。 AI仅用于发现异常、汇集证据和解释规则；涉及违法违规、利益输送或围串标等结论，应由有权人员复核认定。"
    },
    "pathConfig": {
      "hops": [],
      "logic": "AND",
      "constraints": []
    },
