      "logic": "AND",
      "items": [],
      "expression": "WHEN (normalize(supplier_id) != normalize(company_name)) AND (anomaly_score([supplier_id,company_name,bank_account_name,bank_account,verification_status]) >= $anomaly_threshold OR risk_override_flag=TRUE) THEN RISK(\"供应商银行账户户名不一致-异常模型+人工放行\", level=\"高\", action=\"人工复核/按权限阻断\")",
      "expressionLanguage": "DSL",
